[{"order":1,"type":"heading","text":"File Uploads, Downloads, and Native Dialogs in Selenium"},{"order":2,"type":"paragraph","text":"Automating file uploads, managing file downloads, and handling native browser dialogs are common challenges in web testing. Selenium provides robust built-in mechanisms to handle file inputs and JavaScript dialogs, while downloads often require configuring browser options."},{"order":3,"type":"subheading","text":"1. Handling File Uploads"},{"order":4,"type":"paragraph","text":"In Selenium, you do not need to interact with the native OS file picker dialog. If the HTML element is an input of type 'file', you can simply pass the absolute path of the file directly to the sendKeys() method."},{"order":5,"type":"code","text":"WebDriver driver = new ChromeDriver();
driver.get("https://the-internet.herokuapp.com/upload");

WebElement uploadInput = driver.findElement(By.id("file-upload"));
uploadInput.sendKeys("/absolute/path/to/sample.txt");

driver.findElement(By.id("file-submit")).click();"},{"order":6,"type":"subheading","text":"2. Handling File Downloads"},{"order":7,"type":"paragraph","text":"Browsers like Chrome and Firefox block automatic downloads by default during automated testing. To handle downloads, you must configure the browser preferences (ChromeOptions or FirefoxOptions) to specify a custom download directory and disable download prompts."},{"order":8,"type":"code","text":"HashMap<String, Object> chromePrefs = new HashMap<>();
chromePrefs.put("profile.default_content_settings.popups", 0);
chromePrefs.put("download.default_directory", "/path/to/target/folder");

ChromeOptions options = new ChromeOptions();
options.setExperimentalOption("prefs", chromePrefs);

WebDriver driver = new ChromeDriver(options);
driver.get("https://the-internet.herokuapp.com/download");
driver.findElement(By.linkText("some-file.txt")).click();"},{"order":9,"type":"subheading","text":"3. Handling Native Dialogs (Alerts, Confirms, Prompts)"},{"order":10,"type":"paragraph","text":"Selenium's Alert interface allows you to interact with JavaScript-based native dialogs. Once a dialog appears, you switch the driver's focus to the alert and perform actions like accept(), dismiss(), sendKeys(), or getText()."},{"order":11,"type":"code","text":"// Trigger an alert
driver.findElement(By.id("alertButton")).click();

// Switch to the alert and accept it
Alert alert = driver.switchTo().alert();
String alertMessage = alert.getText();
System.out.println(alertMessage);
alert.accept();"},{"order":12,"type":"bullet_point","text":"Use alert.accept() to click 'OK' on alerts and confirmation dialogs."},{"order":13,"type":"bullet_point","text":"Use alert.dismiss() to click 'Cancel' on confirmation dialogs."},{"order":14,"type":"bullet_point","text":"Use alert.sendKeys("text") to input text into a JavaScript prompt dialog before accepting."}]
